{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>About — {{BUSINESS_NAME}}</title>
  <style>
    :root{--glass:#ffffff20;--accent:#7bd389;--muted:#dfeef0;--glass-2:#ffffff10;--text:#e9f7f3}
    html,body{height:100%;margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;color:var(--text);background:linear-gradient(180deg,#09121a 0%,#071018 60%);
      -webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility}
    /* patterned backdrop: inline unique svg + fallback path */
    body::before{content:"";position:fixed;inset:0;opacity:0.08;background-image:url('assets/img/pattern.svg'), radial-gradient(ellipse at 20% 10%,#0a2631 0%,transparent 20%), linear-gradient(120deg,#04232b 0%, #081218 100%);background-repeat:repeat;mix-blend-mode:overlay}
    .wrap{max-width:980px;margin:48px auto;padding:28px;border-radius:16px;background:linear-gradient(135deg, rgba(255,255,255,0.03), rgba(255,255,255,0.01));box-shadow:0 8px 30px rgba(2,6,10,0.6);backdrop-filter: blur(8px);border:1px solid rgba(255,255,255,0.04)}
    nav{display:flex;gap:16px;align-items:center;justify-content:space-between;margin-bottom:18px}
    .nav-left{display:flex;gap:12px;align-items:center}
    .brand{font-weight:600;letter-spacing:0.6px}
    .nav a{color:var(--muted);text-decoration:none;padding:8px;border-radius:8px}
    .nav a:hover{background:var(--glass-2)}
    .hero{display:grid;grid-template-columns:1fr 320px;gap:20px;align-items:center}
    .hero h1{margin:0;font-size:28px;line-height:1.05}
    .tag{color:var(--muted);margin-top:8px}
    .card{background:linear-gradient(180deg,rgba(255,255,255,0.02),rgba(255,255,255,0.01));padding:18px;border-radius:12px;border:1px solid rgba(255,255,255,0.03)}
    .muted{color:var(--muted);font-size:14px}
    .mixer{display:flex;gap:8px;margin-top:12px}
    .mixer button{flex:1;padding:10px;border-radius:10px;border:1px solid rgba(255,255,255,0.04);background:transparent;color:var(--muted);cursor:pointer}
    .mixer button.active{background:linear-gradient(90deg,rgba(123,211,137,0.14),rgba(123,211,137,0.05));border-color:rgba(123,211,137,0.35);color:var(--text)}
    .programs{margin-top:14px;display:grid;gap:10px}
    .program{display:flex;justify-content:space-between;align-items:center;padding:12px;border-radius:10px;border:1px solid rgba(255,255,255,0.02);background:linear-gradient(180deg,#07161a80,#07161a30)}
    .badge{display:inline-flex;gap:8px;align-items:center;padding:6px 8px;border-radius:999px;background:rgba(255,255,255,0.02);font-size:13px}

    /* Proof gallery */
    .proof{margin-top:22px;display:flex;gap:14px;align-items:flex-start}
    .testimony{flex:1;padding:18px;border-radius:12px}
    .testimony p{margin:0;font-size:15px}
    .badges{display:flex;flex-direction:column;gap:8px}
    .cred{display:flex;align-items:center;gap:8px;padding:8px;border-radius:8px;background:rgba(255,255,255,0.02);position:relative}
    .cred svg{width:32px;height:32px}
    .tip{position:absolute;left:110%;top:50%;transform:translateY(-50%);background:#061016;padding:8px;border-radius:6px;border:1px solid rgba(255,255,255,0.04);white-space:nowrap;opacity:0;pointer-events:none;transition:all 180ms}
    .cred:hover .tip{opacity:1}

    footer{margin-top:20px;padding-top:12px;border-top:1px dashed rgba(255,255,255,0.03);display:flex;justify-content:space-between;align-items:center}
    .cta{background:linear-gradient(90deg,var(--accent),#4fc3b1);padding:10px 14px;border-radius:10px;color:#042018;text-decoration:none;font-weight:600}
    small{color:var(--muted)}

    @media(max-width:820px){.hero{grid-template-columns:1fr;}.badges{flex-direction:row}}
  </style>
</head>
<body>
  <div class="wrap">
    <nav>
      <div class="nav-left"><div class="brand">{{BUSINESS_NAME}}</div></div>
      <div class="nav">
        <a href="index.html">Home</a>
        <a href="events.html">Gatherings</a>
        <a href="private-sessions.html">Bespoke</a>
        <a href="pricing.html">Rates</a>
        <a href="about.html" aria-current="page">About</a>
        <a href="faq.html">Queries</a>
        <a href="book.html">Reserve</a>
        <a href="contact.html">Reach</a>
      </div>
    </nav>

    <section class="hero">
      <div>
        <h1>{{TAGLINE}}</h1>
        <div class="tag">A quietly crafted container for collective calm — steady tones, clear timing, practical return.</div>
        <div class="card">
          <div class="muted">Our approach</div>
          <p style="margin-top:6px">We blend tuned bowls, breath-friendly pacing, and gentle voice to shape spaces where attention can soften and re-form. Sessions are designed to be accessible: you arrive as you are, we attend to sound and safety.</p>
          <div class="mixer" style="margin-top:12px">
            <button data-level="gentle" class="active">Gentle</button>
            <button data-level="medium">Medium</button>
            <button data-level="intense">Intense</button>
          </div>
          <div class="programs" id="programs-about">
            <div class="program"><div>
              <div style="font-weight:600">Drift Circle</div>
              <small class="muted">A calm, seated sound frame — good for first-timers</small>
            </div><div class="badge">Sliding scale</div></div>
            <div class="program"><div>
              <div style="font-weight:600">Vessel Session</div>
              <small class="muted">Extended tone + guided return — steady focus</small>
            </div><div class="badge">$45</div></div>
          </div>
        </div>
      </div>

      <aside>
        <div class="card">
          <div style="display:flex;justify-content:space-between;align-items:center">
            <div><strong>Quick proof</strong><div class="muted">Rotating trust and voices</div></div>
            <div style="font-size:12px;color:var(--muted)">Hybrid offerings</div>
          </div>

          <div class="proof">
            <div class="testimony card" id="testimony-about">
              <p>"A steady half-hour that shifted my week — simple, warm, and immediate."</p>
              <div style="margin-top:10px" class="muted">— Lina, {{CITY}}</div>
            </div>
            <div class="badges">
              <div class="cred" data-tip="Seen in our community collaborations"><svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><circle cx="12" cy="12" r="10" stroke="#7bd389" stroke-width="1.6" fill="rgba(123,211,137,0.06)"/></svg><span>Local Collab</span><div class="tip">Partnered with neighborhood centers</div></div>
              <div class="cred" data-tip="Practitioner-led sessions"><svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><rect x="3" y="3" width="18" height="18" rx="4" stroke="#91e2c7" stroke-width="1.6" fill="rgba(145,226,199,0.04)"/></svg><span>Practitioner</span><div class="tip">Lead facilitator certified in somatic care</div></div>
            </div>
          </div>
          <div style="margin-top:12px"><small class="muted">We welcome people with most health histories. See FAQ for contraindications.</small></div>
        </div>
      </aside>
    </section>

    <section style="margin-top:18px">
      <div class="card">
        <strong>How we plan a session</strong>
        <ol style="margin-top:8px;color:var(--muted)">
          <li>Gentle intake — we ask about comfort and hearing.</li>
          <li>Tone architecture — bowls and voice arranged for clear return.</li>
          <li>Return space — cues to re-orient gently and depart rested.</li>
        </ol>
      </div>
    </section>

    <footer>
      <div>
        <small>Questions? Call <a href="tel:{{PHONE}}" style="color:var(--muted);text-decoration:none">{{PHONE}}</a> or email <a href="mailto:{{EMAIL}}" style="color:var(--muted)">{{EMAIL}}</a></small>
      </div>
      <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
    </footer>
  </div>

  <script>
    // Mixer logic (about page) — updates program copy based on chosen intensity
    (function(){
      const buttons = document.querySelectorAll('.mixer button');
      const programs = document.getElementById('programs-about');
      const mapping = {
        gentle:[
          {title:'Drift Circle',meta:'Short guided session — ease into rest',price:'Sliding scale'},
          {title:'Lull Frame',meta:'Soft tones, strong safety cues',price:'$25'}
        ],
        medium:[
          {title:'Vessel Session',meta:'Mid-length tone architecture — steady pacing',price:'$45'},
          {title:'Arc Practice',meta:'Movement-friendly sound and voice',price:'$55'}
        ],
        intense:[
          {title:'Deep Meridian',meta:'Extended resonant work — for seasoned listeners',price:'$75'},
          {title:'Pulse Intensive',meta:'Focused recalibration with sustained bowls',price:'$95'}
        ]
      };

      function render(level){
        programs.innerHTML='';
        mapping[level].forEach(p=>{
          const el = document.createElement('div');el.className='program';
          el.innerHTML='<div><div style="font-weight:600">'+p.title+'</div><small class="muted">'+p.meta+'</small></div><div class="badge">'+p.price+'</div>';
          programs.appendChild(el);
        });
      }

      buttons.forEach(b=>b.addEventListener('click',()=>{
        buttons.forEach(x=>x.classList.remove('active'));b.classList.add('active');render(b.dataset.level);
      }));
    })();

    // Proof gallery rotation
    (function(){
      const notes = [
        {text:'"A steady half-hour that shifted my week — simple, warm, and immediate."',who:'Lina, {{CITY}}'},
        {text:'"Clearly led, soothing, no fuss. I left with a different pace."',who:'Marcus, {{STATE}}'},
        {text:'"I slept in a way I hadn\'t in months. Gentle, precise."',who:'Priya'}
      ];
      let i=0;const el=document.getElementById('testimony-about');
      setInterval(()=>{i=(i+1)%notes.length;el.innerHTML='<p>'+notes[i].text+'</p><div style="margin-top:10px" class="muted">— '+notes[i].who+'</div>'},4200);
    })();
  </script>
</body>
</html>"} 
{"path":"faq.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Questions — FAQ — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#081318;--glass:#ffffff12;--accent:#7bd389;--muted:#bcd9d1;--text:#e8fbf4}
    body{margin:0;font-family:Inter,system-ui,Segoe UI,Roboto,Arial;background:linear-gradient(180deg,#071016 0%,#031018 100%);color:var(--text);-webkit-font-smoothing:antialiased}
    .container{max-width:940px;margin:36px auto;padding:22px;border-radius:14px;background:linear-gradient(180deg,rgba(255,255,255,0.02),rgba(255,255,255,0.006));backdrop-filter:blur(6px);border:1px solid rgba(255,255,255,0.03)}
    header{display:flex;justify-content:space-between;align-items:center}
    nav a{color:var(--muted);text-decoration:none;margin-left:10px}
    h1{margin:6px 0}
    .grid{display:grid;grid-template-columns:1fr 320px;gap:18px;margin-top:18px}
    .qa{background:transparent;padding:12px;border-radius:10px}
    .q{padding:12px;border-radius:8px;margin-bottom:10px;background:linear-gradient(180deg,rgba(255,255,255,0.012),rgba(255,255,255,0.005));border:1px solid rgba(255,255,255,0.02)}
    .muted{color:var(--muted)}
    .toggle{display:flex;gap:8px;margin-top:8px}
    .cta{display:inline-block;padding:10px 12px;border-radius:10px;background:linear-gradient(90deg,var(--accent),#4fc3b1);color:#042018;text-decoration:none;font-weight:600}
    .notice{font-size:13px;color:var(--muted);margin-top:10px}
    .badges{display:flex;gap:8px;flex-wrap:wrap}
    .cred{padding:8px;border-radius:8px;background:rgba(255,255,255,0.02);cursor:default;position:relative}
    .tip{position:absolute;left:105%;top:50%;transform:translateY(-50%);background:#041617;padding:8px;border-radius:6px;border:1px solid rgba(255,255,255,0.04);white-space:nowrap;opacity:0;pointer-events:none;transition:all 160ms}
    .cred:hover .tip{opacity:1}

    @media(max-width:880px){.grid{grid-template-columns:1fr}.cred{font-size:13px}}
  </style>
</head>
<body>
  <div class="container">
    <header>
      <div>
        <div style="font-weight:600">{{BUSINESS_NAME}}</div>
        <nav style="margin-top:6px">
          <a href="index.html">Home</a>
          <a href="events.html">Gatherings</a>
          <a href="pricing.html">Rates</a>
          <a href="about.html">About</a>
          <a href="book.html">Reserve</a>
        </nav>
      </div>
      <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
    </header>

    <h1>Questions & Considerations</h1>
    <div class="grid">
      <main>
        <section class="qa">
          <div class="q"><strong>Who benefits from these sessions?</strong><div class="muted" style="margin-top:8px">People looking to downshift attention, recover from stress, or improve rest. Sessions support steady breathing and gentle somatic awareness.</div></div>

          <div class="q"><strong>Do I need experience?</strong><div class="muted" style="margin-top:8px">No—most offerings are accessible. We structure time and provide gentle cues to help you return from sound without strain.</div></div>

          <div class="q"><strong>Are sessions loud?</strong><div class="muted" style="margin-top:8px">We calibrate to the room. You can choose gentle / medium / intense textures when booking. Intense does not mean harmful volume—it's about sustained resonance and density.</div></div>

          <div class="q"><strong>Contraindications & safety</strong>
            <div class="muted" style="margin-top:8px">Most people attend safely. Please consult your physician before attending if you have any of the following: epilepsy or seizure disorder, recent head injury, recent eye surgery, sensitivity to sustained low frequencies, pacemaker or certain implanted medical devices, or are in the early stages of pregnancy. If you are unsure, contact us at <a href="mailto:{{EMAIL}}" style="color:var(--muted);text-decoration:none">{{EMAIL}}</a>. Staff will offer quieter placement and can adapt the practice.</div>
          </div>

          <div class="q"><strong>Privacy & accessibility</strong><div class="muted" style="margin-top:8px">We hold space that is fragrance-free by request and wheelchair accessible at select venues. Notify us when reserving for specific accommodations.</div></div>
        </section>

        <section style="margin-top:10px">
          <strong class="muted">Bookings & fees</strong>
          <div class="q"><strong>Can I book privately?</strong><div class="muted" style="margin-top:8px">Yes — bespoke sessions and workplace gatherings are offered. See private sessions page for options and sliding-scale framing.</div></div>
          <div class="q"><strong>Cancellation policy</strong><div class="muted" style="margin-top:8px">Please notify us 24 hours in advance to reschedule or receive a partial credit. Late cancellations may forfeit the fee.</div></div>
        </section>

      </main>

      <aside>
        <div class="card" style="padding:12px;border-radius:10px;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);border:1px solid rgba(255,255,255,0.02)">
          <strong>Proof & trust</strong>
          <div class="notice">Voices and local partnerships rotate — samples below.</div>

          <div class="badges" style="margin-top:12px">
            <div class="cred">Local Clinic<div class="tip">Support work with community health partners</div></div>
            <div class="cred">Arts Collective<div class="tip">Featured collaboration with regional arts groups</div></div>
            <div class="cred">Somatic Guide<div class="tip">Lead facilitator with somatic training</div></div>
          </div>

          <div style="margin-top:12px">
            <small class="muted">Testimonial rotation:</small>
            <div id="testimony-faq" style="margin-top:10px;background:transparent;padding:10px;border-radius:8px"></div>
          </div>

          <div style="margin-top:12px"><a class="cta" href="book.html">Find your texture</a></div>
        </div>
      </aside>
    </div>

    <footer style="margin-top:18px;display:flex;justify-content:space-between;align-items:center">
      <small class="muted">Questions? Call <a href="tel:{{PHONE}}" style="color:var(--muted);text-decoration:none">{{PHONE}}</a></small>
      <div class="muted">© <span id="year"></span> {{BUSINESS_NAME}}</div>
    </footer>
  </div>

  <script>
    // Testimonial rotate for FAQ
    (function(){
      const notes=[
        {t:'"A calm, clear session with real attention to comfort."',w:'— Noelle'},
        {t:'"The facilitator listened first. I felt safe the whole way."',w:'— Aaron'},
        {t:'"I booked again for a team reset. It grounded the group."',w:'— Maya'}
      ];let i=0;const el=document.getElementById('testimony-faq');
      function show(){el.innerHTML='<div style="font-weight:600">'+notes[i].t+'</div><div class="muted" style="margin-top:6px">'+notes[i].w+'</div>'}
      show();setInterval(()=>{i=(i+1)%notes.length;show();},3800);
      document.getElementById('year').textContent=new Date().getFullYear();
    })();
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Reserve — Book a Session — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#031217;--glass:#ffffff10;--accent:#89e0b8;--muted:#b9ded3;--text:#e9fdf6}
    body{margin:0;font-family:Inter,system-ui,Segoe UI,Roboto,Arial;background:linear-gradient(180deg,#031217 0%,#021014 100%);color:var(--text)}
    .wrap{max-width:920px;margin:36px auto;padding:22px;border-radius:14px;background:linear-gradient(180deg,rgba(255,255,255,0.02),rgba(255,255,255,0.004));backdrop-filter:blur(6px);border:1px solid rgba(255,255,255,0.03)}
    header{display:flex;justify-content:space-between;align-items:center}
    nav a{color:var(--muted);text-decoration:none;margin-left:10px}
    h1{margin:10px 0}
    .booking{display:grid;grid-template-columns:1fr 320px;gap:18px;margin-top:18px}
    .form{padding:12px;border-radius:10px}
    label{display:block;margin-top:10px;color:var(--muted);font-size:14px}
    input,select,textarea{width:100%;padding:10px;margin-top:6px;border-radius:8px;border:1px solid rgba(255,255,255,0.03);background:transparent;color:var(--text)}
    .row{display:flex;gap:8px}
    .btn{display:inline-block;padding:10px 12px;border-radius:10px;background:linear-gradient(90deg,var(--accent),#4fc3b1);color:#042018;text-decoration:none;font-weight:700;border:none;cursor:pointer}
    .alt{background:transparent;border:1px solid rgba(255,255,255,0.04);color:var(--muted)}
    .program-list{margin-top:12px;display:grid;gap:8px}
    .program{padding:10px;border-radius:8px;border:1px solid rgba(255,255,255,0.02);display:flex;justify-content:space-between;align-items:center}
    .muted{color:var(--muted)}
    .note{font-size:13px;color:var(--muted);margin-top:8px}

    @media(max-width:880px){.booking{grid-template-columns:1fr}} 
  </style>
</head>
<body>
  <div class="wrap">
    <header>
      <div>
        <div style="font-weight:600">{{BUSINESS_NAME}}</div>
        <nav style="margin-top:6px">
          <a href="index.html">Home</a>
          <a href="events.html">Gatherings</a>
          <a href="about.html">About</a>
          <a href="faq.html">Queries</a>
        </nav>
      </div>
      <a class="btn" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
    </header>

    <h1>Reserve a session</h1>
    <div class="booking">
      <form class="form" id="booking-form" onsubmit="return false;">
        <label>Full name<input type="text" id="name" placeholder="Your name" required></label>
        <label>Email<input type="email" id="email" placeholder="you@domain.com" required></label>
        <label>Phone<input type="tel" id="phone" placeholder="{{PHONE}}"></label>

        <label>Preferred sound texture</label>
        <div class="row" id="mixer-book">
          <button type="button" class="alt" data-level="gentle">Gentle</button>
          <button type="button" class="alt active" data-level="medium">Medium</button>
          <button type="button" class="alt" data-level="intense">Intense</button>
        </div>

        <div class="program-list" id="programs-book">
          <!-- populated by JS -->
        </div>

        <label>Notes (comfort, hearing, accessibility)</label>
        <textarea id="notes" rows="3" placeholder="Tell us about any needs..."></textarea>

        <div style="margin-top:12px;display:flex;gap:8px;align-items:center">
          <button id="submit" class="btn">Secure a spot</button>
          <button id="call" class="alt" onclick="location.href='tel:{{PHONE}}'">Call to reserve</button>
        </div>

        <div class="note">By booking you confirm you have read the contraindications in the FAQ. If uncertain, contact <a href="mailto:{{EMAIL}}" style="color:var(--muted)">{{EMAIL}}</a>.</div>
      </form>

      <aside class="form">
        <strong>Quick recommendations</strong>
        <div class="muted" style="margin-top:8px">Choose a texture that matches your current threshold. You can change it on arrival.</div>

        <div style="margin-top:12px" id="suggestion">
          <div class="program"><div><strong id="rec-title">Vessel Session</strong><div class="muted" style="font-size:13px">Recommended for steady return</div></div><div class="muted" id="rec-price">$45</div></div>
        </div>

        <div style="margin-top:12px">
          <strong>Proof</strong>
          <div id="proof-book" style="margin-top:8px"></div>
        </div>

      </aside>
    </div>

    <footer style="margin-top:18px;display:flex;justify-content:space-between;align-items:center">
      <small class="muted">Questions? Call <a href="tel:{{PHONE}}" style="color:var(--muted);text-decoration:none">{{PHONE}}</a></small>
      <div class="muted">Serving {{CITY}}, {{STATE}}</div>
    </footer>
  </div>

  <script>
    // Booking page: mixer + program recommendations
    (function(){
      const mapping = {
        gentle:[{title:'Drift Circle',price:'Sliding scale',desc:'30 min gentle seating'},{title:'Lull Frame',price:'$25',desc:'Soft tones + rest cues'}],
        medium:[{title:'Vessel Session',price:'$45',desc:'45 min tone architecture'},{title:'Arc Practice',price:'$55',desc:'Movement-friendly sound'}],
        intense:[{title:'Deep Meridian',price:'$75',desc:'60 min sustained resonance'},{title:'Pulse Intensive',price:'$95',desc:'Focused recalibration'}]
      };

      const buttons = document.querySelectorAll('#mixer-book button');
      const programsEl = document.getElementById('programs-book');
      const recTitle = document.getElementById('rec-title');
      const recPrice = document.getElementById('rec-price');
      const suggestion = document.getElementById('suggestion');

      function setActive(el){buttons.forEach(b=>b.classList.remove('active'));el.classList.add('active')}

      function render(level){
        programsEl.innerHTML='';
        mapping[level].forEach(p=>{
          const d=document.createElement('div');d.className='program';d.innerHTML='<div><strong>'+p.title+'</strong><div class="muted" style="font-size:13px">'+p.desc+'</div></div><div class="muted">'+p.price+'</div>';
          d.addEventListener('click',()=>{recTitle.textContent=p.title;recPrice.textContent=p.price});
          programsEl.appendChild(d);
        });
        // default suggestion
        recTitle.textContent=mapping[level][0].title;recPrice.textContent=mapping[level][0].price;
      }

